                        '\\' -> sb.append('\\')
                        '\'' -> sb.append('\'')
                        '"' -> sb.append('"')
                        else -> sb.append(nextChar)
                    }
                } else {
                    sb.append(c)
                }
                i++
            }
            if (!foundEnd) {
                throw TokenizeException("Unterminated string", startPos)
            }
            tokens.add(Token.Str(sb.toString(), startPos))
            prevWasOpOrParenOpen = false
            continue
        }

        // Check for numbers
        // Optional leading '-' only if prevWasOpOrParenOpen
        var isNegative = false
        if (ch == '-' && prevWasOpOrParenOpen) {
            // Check if it's a negative number
            if (i + 1 < len && (input[i + 1].isDigit())) {
                isNegative = true
                i++ // skip '-'
            } else {
                // '-' not followed by digit, and prevWasOpOrParenOpen is true
                // This is an error because '-' is not an operator
                throw TokenizeException("Unexpected character '-'", startPos)
            }
        }

        if (ch == '-' && !prevWasOpOrParenOpen) {
            throw TokenizeException("Unexpected character '-'", startPos)
        }

        // Check for numbers (positive or negative)
        if (i < len && input[i].isDigit()) {
            val numStart = i
            var hasDot = false
            var hasDigits = false
            while (i < len && (input[i].isDigit() || input[i] == '.')) {
                if (input[i] == '.') {
                    if (hasDot) {
                        throw TokenizeException("Invalid number", numStart)
                    }
                    hasDot = true
                } else {
                    hasDigits = true
                }
                i++
            }
            if (!hasDigits) {
                throw TokenizeException("Invalid number", numStart)
            }
            if (hasDot && i > 0 && input[i - 1] == '.') {
                // Ends with dot, e.g. "5."
                throw TokenizeException("Invalid number", numStart)
            }
            val numStr = input.substring(numStart, i)
            val value = numStr.toDouble()
            val finalValue = if (isNegative) -value else value
            tokens.add(Token.Num(finalValue, startPos))
            prevWasOpOrParenOpen = false
            continue
        }

        // If we reached here and isNegative is true, it means we had '-' but no digit followed
        // This case is already handled above, but just in case
        if (isNegative) {
            throw TokenizeException("Invalid number", startPos)
        }

        // Check for identifiers
        if (ch.isLetter() || ch == '_') {
            val idStart = i
            i++
            while (i < len && (input[i].isLetterOrDigit() || input[i] == '_' || input[i] == '.')) {
                // Dots are allowed after the first char
                i++
            }
            val name = input.substring(idStart, i)
            tokens.add(Token.Ident(name, startPos))
            prevWasOpOrParenOpen = false
            continue
        }

        // If we get here, it's an invalid character
        throw TokenizeException("Unexpected character '$ch'", startPos)
    }

    return tokens
}
